def the_frame(case, data):
    """F1 — Deut 8:1: all the commandment, that you may live and multiply and go in and possess (4:1 by CALL — the readback row), the oath's seats, no receipt"""
    del P_[:]
    ask = case['ask']
    if ask == 'all_the_commandment':
        ink('8:1', '"ALL THE COMMANDMENT which I command you this day you shall keep to do, that you may live and multiply" — "all the commandment" %s (eight seats, all this book\'s); "which I command you this day" %d seats in the book; "and multiply" the form\'s one seat %s; the paragogic nun %s' % (P('כל', 'המצוה'), len(P('אשר', 'אנכי', 'מצוך', 'היום', books=('Deut',))), U('ורביתם'), NUN[1]))
        dat('the frame: no divine frame, no "saying" — the whole chapter Moses\' voice; the second person both numbers at 8:1 (the frame) and 8:19, plural alone at 8:20, singular in sixteen verses, neither at 8:8')
        return out("all the commandment (8:1) — 'all the commandment which I command you this day' the book's eight seats, this the frame's; 'that you may live and multiply' the plural with the nun; no write", ['accepted'])
    if ask == 'live_and_possess':
        ink('8:1', '"that you may live and multiply and go in and possess the land which the LORD swore to your fathers" — "and go in and possess" %s (4:1, 8:1, 11:8 the three seats); "that you may live" %s; the shared run with 4:1 %s' % (P('ובאתם', 'וירשתם'), P('למען', 'תחיון') + P('למען', 'תחיה') + P('למען', 'תחיו'), SHARED(('Deut', 8, 1), ('Deut', 4, 1))))
        move('cold_run_obey_horeb (CALL) — OH.the_exhortation(hear_and_do) = %s' % (OH_HEAR[0][:60],), "4:1's exhortation — 'hear the statutes and the judgments … that you may live and go in and possess the land': the clause said again at the frame; 8:1's 'keep to do' for 4:1's 'hear … to do'")
        dat('the readback row 8:1 VERBATIM in kind — computed %s tokens against 4:1\'s %s, %s shared' % DELTA['live_8_1'])
        return out("live and possess (8:1) — 4:1's exhortation's clause 'that you may live and go in and possess the land' (OH by CALL): the readback row VERBATIM in kind; 4:1, 8:1, 11:8 the three seats", ['accepted'])
    if ask == 'the_oath_seats':
        ink('8:1, 8:18', '"which the LORD swore to your fathers" (8:1) … "his covenant which he swore to your fathers" (8:18) — the swearing verb (the lemma %s) no number, the book\'s %d seats; the oath\'s NOUN (7:8\'s, the lemma 7621) absent from the chapter %s; "which he swore to your fathers" %s' % (lemma_of('Deut', 8, 1, 'נשבע'), len(LEMV('7650', books=('Deut',))), [x for x, l in zip(W8(1) + W8(18), byl[('Deut', 8, 1)] + byl[('Deut', 8, 18)]) if l == '7621'], P('אשר', 'נשבע', 'לאבתיך')))
        move('cold_run_seven_nations (CALL) — SN.the_holy_people(the_oath) = %s' % (SN_OATH[0][:70],), "7:8's form on the oath's three tape lines — sworn_by_himself (Genesis 22:16-18), oath_upheld (26:3-5), visitation_promised (50:24): the noun starred there, the verb here unstarred, no number")
        return out("the oath's seats (8:1, 8:18) — 'swore' twice, no number (7:8's noun the parser's star; here the verb alone): the oath's three lines on the tape (SN by CALL); Onkelos 'established' for 'swore' at both", ['accepted'])
    if ask == 'no_receipt':
        ink('8:1-20', 'the register gate\'s finder\'s rule on the chapter (as/according to all that … commanded … the LORD): seats %s (chapter 5\'s %s and chapter 1\'s %s for the rule\'s witness); "which I command you" (8:1, 8:11) the GIVING, not a receipt' % (receipt_seats(8), receipt_seats(5), receipt_seats(1)))
        dat("the register gate --strict unmoved: DECLARED 100, no seat in chapter 8 (the design's measurement)")
        return out("no receipt (8:1-20) — the register gate's finder (as / according to all that … commanded … the LORD) finds no seat in the chapter: 'which I command you' the giving, not a receipt; DECLARED 100 unmoved", ['accepted'])
    return out('no verdict in span', [FX.NONE])


